WITH visible_collision_members AS (
) SELECT record_type, kind, normalized_value, COUNT(*) AS collision_size, MAX(rebuilt_at) AS rebuilt_at FROM visible_collision_members
record_type = #{recordType} AND kind = #{kind}
GROUP BY record_type, kind, normalized_value HAVING COUNT(*) >= 2 ORDER BY record_type, kind, normalized_value LIMIT #{limit} OFFSET #{offset}

WITH visible_collision_members AS (

)
SELECT COUNT(*)
FROM (
  SELECT record_type, kind, normalized_value
  FROM visible_collision_members

    record_type = #{recordType}
    AND kind = #{kind}

  GROUP BY record_type, kind, normalized_value
  HAVING COUNT(*) >= 2
) collision_groups

WITH visible_collision_members AS (

),
sized_collision_members AS (
  SELECT record_type,
         kind,
         normalized_value,
         record_id,
         record_name,
         COUNT(*) OVER (
           PARTITION BY record_type, kind, normalized_value
         ) AS collision_size
  FROM visible_collision_members
)
SELECT record_type, kind, normalized_value, record_id, record_name
FROM sized_collision_members
WHERE collision_size >= 2
  AND (

      (
        record_type = #{group.recordType}
        AND kind = #{group.kind}
        AND normalized_value = #{group.normalizedValue}
      )

  )
ORDER BY record_type, kind, normalized_value, record_id
